{
  "schema_version": 1,
  "action": "set_policy",
  "policy": {
    "model": "transformer",
    "window": 3,
    "threshold_q": 0.9999,
    "persistence": 5
  },
  "intent_understood_as": "minimize_false_alarms",
  "reason": "Intent demands minimal false alarms while keeping real attack detection. Transformer avoids catastrophic per-attack failures and has the best DNS detection delay (10.9s). Using q=0.9999 (most conservative threshold) with persistence=5 maximally suppresses false alarms. At default threshold transformer already achieves 0.01 false alarms/hour; this configuration will drive false alarms near zero while still detecting known attacks like DNS."
}
